# 数据文件：src/components/FullscreenLayout.tsx
# slug = src_components_FullscreenLayout_tsx
# 规则：一个源文件 = 一个数据文件；中文用三引号；禁止英文双引号 " 与反斜杠 \（用「」/『』代替）。
ANNOTATIONS = [
    (1, 'before', '''本文件是 REPL 的全屏布局壳与未读分隔线机制三合一：useUnseenDivider、未读计数、未读定位三件纯逻辑，FullscreenLayout 双模式布局（全屏等于粘性 ScrollBox 加 flex 钉底；非全屏等于顺序渲染走终端自带回滚），以及未读 pill、粘性提示头、两个浮层等 chrome 零件。本文件注释密度全仓罕见——几乎所有 DECSTBM 与粘性滚动的坑都写进了注释，值得整读。'''),
    (20, 'before', '''模态面板底部固定保留 2 行对话回滚（peek），让用户在弹层之下仍能看到上下文尾行；ModalContext 的高度预算也基于它扣减。'''),
    (26, 'before', '''滚动 chrome 上下文：VirtualMessageList 里的 StickyTracker 通过这个 context 写「粘性提示」，避免回调沿 Messages、REPL、FullscreenLayout 逐层穿线；setter 引用稳定，消费方不会因此重渲染。'''),
    (31, 'before', '''Props 契约：scrollable 是滚动主体，bottom 钉底，overlay 叠加在滚动区内（权限请求用），bottomFloat 浮在滚动区右下（语音气泡用），modal 是斜杠命令弹层；另有滚动引用、未读 pill 与粘性头的开关与计数。'''),
    (86, 'before', '''未读分隔线 hook：用户向上滚离底部时记录快照——消息数与 scrollHeight 各存一份，前者决定分隔线画在消息数组的哪个下标，后者是分隔线在滚动内容坐标系里的 y 位置。pillVisible 故意不放在这里：布局层用 useSyncExternalStore 直接订阅 ScrollBox，每帧滚动不会重渲染 REPL。'''),
    (104, 'before', '''dividerIndex 是 state（变更会重渲染，但一次滚动会话只变约两次）；dividerYRef 是 ref（只写不触发渲染）。'''),
    (110, 'before', '''countRef 在渲染体里直接同步当前消息数（不走 useEffect）——滚轮事件可能落在「消息追加渲染」与「effect 刷写」之间，用 effect 会拿到旧计数导致基线差一。React Compiler 在这里跳过优化，可接受：hook 只在 REPL 实例化一次。'''),
    (116, 'before', '''scrollHeight 快照 ref：onScrollAway 里要同步读（setState 批处理下同一回调里读后写做不到），布局层的 pillVisible 订阅也要读它；null 表示仍钉在底部。'''),
    (117, 'before', '''onRepin（提交或滚回底部）只清 dividerIndex 不清 ref：同一 stdin 批次里赶来的触控板惯性滚轮事件会看到 null 而重新快照、覆盖掉这次清除；ref 的清空推迟到下方 useEffect，等 React 提交完 null 状态再放行。'''),
    (125, 'before', '''onScrollAway 先做「下方无内容」早退，覆盖两种坑：空会话滚上也会断粘性但没东西可跳；点击选区在底部时会 scrollTo 当前位置断粘性防流式内容位移，scrollTop 仍在最大值——pendingDelta 补上累积未落地的滚动量，否则从底部滚上会被误判成没动。'''),
    (141, 'before', '''只在第一次滚离时快照：onScrollAway 每次滚动都触发，这个 null 守卫保住首次基线——第二次 PageUp 不会重置计数，后续调用只是 ref 级空操作。'''),
    (147, 'before', '''jumpToNew 用 scrollToBottom 而非 scrollTo 分隔线 y：scrollToBottom 置 stickyScroll 为 true 让虚拟滚动挂上尾部并钉住 scrollTop；scrollTo 会关掉粘性、在 React 重渲染前被夹回原位停在半路。分隔线保留（下标不清），让用户看到新消息从哪开始。'''),
    (168, 'before', '''双向同步 effect：repin 后把 ref 清成 null（拦住竞态滚轮的误快照）；clear、rewind、切换队友视图等导致消息数跌破分隔线下标时整体作废——否则分隔线指向不存在的消息。'''),
    (176, 'before', '''shiftDivider 服务向上无限加载历史：消息从头部插入时分隔线下标与 y 快照同步平移，保持指向同一条消息。'''),
    (200, 'before', '''未读计数：把分隔线之后的消息折算成「几条新消息」——按非 assistant 到 assistant 的跳变数计数，且只算真正带文本的条目；纯工具调用条目与进度消息跳过，避免「搜索了 13 个模式」这种输出也点亮 pill。'''),
    (210, 'before', '''纯工具调用条目跳过时 prevWasAssistant 不更新：同一 API 响应里的 tool_use 块加文本块算同一条消息。'''),
    (217, 'before', '''判定 assistant 条目是否带可见文本：content 里存在非空 text 块即为真。'''),
    (239, 'before', '''组装未读对象给 REPL 传给 Messages 与 pill：锚点消息要先跳过进度与不渲染的附件——Messages 那边渲染前就把它们过滤掉了，锚着它们的 UUID 会查无此消息（CC-724 修复）。'''),
    (251, 'before', '''count 下限 1：只要分隔线之后来了任何消息（哪怕是被计数跳过的纯工具条目），pill 就从「跳到底部」翻成「1 条新消息」——没有这个下限，整段工具调用序列期间 pill 会一直假装没新东西。'''),
    (270, 'before', '''布局主体：全屏模式滚动内容进粘性 ScrollBox、底部内容 flexbox 钉住；非全屏模式四个槽位顺序渲染，沿用终端主屏回滚。全屏对内部用户默认开、对外部用户默认关，环境变量 CLAUDE_CODE_NO_FLICKER 可翻转；AlternateScreen 包裹层在 REPL 根上，保证没有东西能渲染到它外面。'''),
    (329, 'before', '''pillVisible 用 useSyncExternalStore 订阅 ScrollBox：快照是布尔值（视口底是否未到分隔线 y），每帧滚动只在布尔翻转时才触发重渲染；subscribe 把监听者接到 scrollRef 指向的 ScrollBox 上。'''),
    (338, 'before', '''全屏分支：以下全部 chrome（粘性头、pill、浮层、弹层）只在这个模式存在。'''),
    (361, 'before', '''ScrollBox 三件事：flexGrow 吃满剩余空间、stickyScroll 开粘底、paddingTop 在有粘性头时收为 0（头已占一行）；overlay 渲染在消息之后、随内容一起滚。'''),
    (372, 'before', '''pill 显示条件四合一：未被强制隐藏、pillVisible 为真、没有 overlay 盖着；count 大于 0 显示「N 条新消息」，否则「跳到底部」。'''),
    (414, 'before', '''底部槽位：建议浮层与对话框浮层先渲染（绝对定位画在输入框上方），bottom 内容外包 overflowY 隐藏的 flex 容器并限高一半——输入区再高也不能吃掉一半屏幕。'''),
    (422, 'before', '''斜杠命令弹层：绝对定位贴底、盖住 ScrollBox 与底部槽位，顶部一行重复字符画的分隔线，内容区水平内边距 2；外面包 ModalContext 把可用高度（终端行数减 peek 再减分隔线）与宽度（减 4）下发给内部组件，让弹层内的 Pane 与 Dialog 跳过自己的画框。'''),
    (448, 'before', '''非全屏路径：四个槽位顺序塞进 fragment，交给终端主屏的既有回滚机制，本文件的所有 chrome 都不渲染。'''),
    (491, 'before', '''未读 pill（Slack 式胶囊）：绝对定位钉在滚动区底行中央，只遮住胶囊文字那一小段；DECSTBM 挪动像素造成的滚动拖影在 Ink 渲染层修复（render-node-to-output 的第三遍扫描）。'''),
    (551, 'before', '''粘性提示头：滚进历史时把当前轮次的用户提示钉在视口上方一行，点击跳回该提示。关键取舍——高度固定 1 行（长提示截断）：变高头部会让 ScrollBox 每次切换粘性提示时整体位移 1 行，DECSTBM 区域顶跟着动，diff 引擎看到「全部移动」，画面跳动。'''),
    (599, 'before', '''斜杠建议浮层：从 promptOverlayContext 门控（portal 化）渲染在输入框上方；渲染器对绝对定位元素的负 y 坐标夹到 0，所以列表超出视口顶部时最好的匹配仍在可见区。故意不设 minHeight 与 flex-end——会在列表不满时制造空行，把可见项往下挤进输入区。'''),
    (621, 'before', '''对话框浮层：AutoModeOptInDialog 从 PromptInput portal 过来，与建议浮层同一套「逃离裁剪」模式；树序靠后所以两者同时出现时盖在建议上面（正常不应同时出现）。'''),
]
